pub fn removeAtIndex(self: *Watcher, index: WatchItemIndex, hash: HashType, parents: []HashType, comptime kind: WatchItem.Kind) void {
        _ = bun.assert((index != no_watch_item));
        self.evict_list[cp_cast_int(usize, self.evict_list_i)] = index;
        self.evict_list_i = (self.evict_list_i + (if (comptime @typeInfo(WatchItemIndex) == .@"enum" and (@typeInfo(@TypeOf(1)) == .int or @typeInfo(@TypeOf(1)) == .comptime_int)) @as(WatchItemIndex, @enumFromInt(1)) else @as(WatchItemIndex, 1)));
        if (comptime (kind == .directory)) {
            for (cp_iter_slice(parents)) |parent| {
                _ = &parent;
                if ((parent == hash)) {
                    self.evict_list[cp_cast_int(usize, self.evict_list_i)] = @as(WatchItemIndex, @truncate(parent));
                    self.evict_list_i = (self.evict_list_i + (if (comptime @typeInfo(WatchItemIndex) == .@"enum" and (@typeInfo(@TypeOf(1)) == .int or @typeInfo(@TypeOf(1)) == .comptime_int)) @as(WatchItemIndex, @enumFromInt(1)) else @as(WatchItemIndex, 1)));
                }
            }
        }
}

pub fn getResolveWatcher(self: *Watcher) bun.resolver.AnyResolveWatcher {
        const RW = bun.resolver.ResolveWatcher(*Watcher, onMaybeWatchDirectory);
        return RW.init(self);
}

pub fn onMaybeWatchDirectory(self: *Watcher, file_path: []const u8, dir_fd: bun.FD) void {
        if (((std.mem.indexOf(u8, file_path, "node_modules") == null) and (std.mem.indexOf(u8, file_path, self.fs.top_level_dir) != null))) {
            _ = self.addDirectory(dir_fd, file_path, Watcher.getHash(file_path), false);
        }
}
pub const ChangedFilePath = ?[:0]u8;
pub const OnFileUpdateFn = *const fn (*anyopaque, []WatchEvent, []ChangedFilePath, WatchList) void;
pub const OnErrorFn = *const fn (*anyopaque, bun.sys.Error) void;
const PackageJSON = PackageJsonPkg.PackageJSON;
const Environment = bun.Environment;
const FeatureFlags = bun.FeatureFlags;
const BunMutex = bun.Mutex;
const Output = bun.Output;
const strings = bun.strings;
const DebugLogScope = bun.Output.Scoped(.watcher, .visible);
const log = DebugLogScope.log;
pub const max_count = 128;
pub const requires_file_descriptors = (switch (Environment.os) {
.mac, .freebsd => true,
else => false,
});
pub const watch_open_flags: i32 = (if (Environment.isMac) bun.c.O_EVTONLY else bun.O.RDONLY);
pub const Event = WatchEvent;
pub const Item = WatchItem;
pub const ItemList = WatchList;
pub const WatchList = std.MultiArrayList(WatchItem);
pub const HashType = u32;
pub const WatchItemIndex = u16;
pub const max_eviction_count = 8096;
const no_watch_item: WatchItemIndex = std.math.maxInt(WatchItemIndex);
const Platform = (switch (Environment.os) {
.linux => INotifyWatcher,
.mac, .freebsd => KEventWatcher,
.windows => WindowsWatcher,
.wasm => @compileError("Unsupported platform"),
});
const EventListIndexType = (if (Environment.isLinux) Platform.EventListIndex else u0);

pub fn InitWrapped(comptime T: type) type {
        return struct {

pub fn onFileUpdateWrapped(ctx_opaque: *anyopaque, events: []WatchEvent, changed_files: []ChangedFilePath, watchlist: WatchList) void {
            {
                _ = T.onFileUpdate(@as(*T, @ptrCast(@alignCast(ctx_opaque))), events, changed_files, watchlist);
            }
    }

pub fn onErrorWrapped(ctx_opaque: *anyopaque, e: bun.sys.Error) void {
            {
                if (@hasDecl(T, "onWatchError")) {
                    _ = T.onWatchError(@as(*T, @ptrCast(@alignCast(ctx_opaque))), e);
                } else {
                    _ = T.onError(@as(*T, @ptrCast(@alignCast(ctx_opaque))), e);
                }
            }
    }
};
